/* ---------------- orbit construction (mirrors R105/R106/R107/R109/R112/R113/R116 r65 orbitMain) ---------------- */

type Small4 = { readonly u: number; readonly v: number; readonly w: number }

const SU = [9, 12, 1, 8, 3, 20, 130]
const SV = [9, 1, 130, 20, 8, 3, 12]
const SW = [9, 132, 10, 5, 18, 8, 1]

function bit2(packed: number, row: number, col: number): boolean {
  const bit = 1 << (2 * row + col)
  return (packed & bit) !== 0 || ((packed >> 4) & bit) !== 0
}

function mask4of(packed: number): number {
  let m = 0
  for (let i = 0; i < 2; i++) {
    for (let j = 0; j < 2; j++) {
      if (bit2(packed, i, j)) m |= 1 << (i * 2 + j)
    }
  }
  return m
}

const GL2: readonly (readonly number[])[] = (() => {
  const out: number[][] = []
  for (let a = 0; a < 2; a++) {
    for (let b = 0; b < 2; b++) {
      for (let c = 0; c < 2; c++) {
        for (let d = 0; d < 2; d++) {
          if ((a * d) ^ (b * c)) out.push([a, b, c, d])
        }
      }
    }
  }
  return out
})()

function inv2(M: readonly number[]): number[] {
  return [M[3] ?? 0, M[1] ?? 0, M[2] ?? 0, M[0] ?? 0]
}

function tr2(M: readonly number[]): number[] {
  return [M[0] ?? 0, M[2] ?? 0, M[1] ?? 0, M[3] ?? 0]
}

function kron2(P: readonly number[], M: readonly number[]): number[][] {
  const K: number[][] = []
  for (let i = 0; i < 2; i++) {
    for (let j = 0; j < 2; j++) {
      const row: number[] = []
      for (let ip = 0; ip < 2; ip++) {
        for (let jp = 0; jp < 2; jp++) row.push((P[i * 2 + ip] ?? 0) & (M[j * 2 + jp] ?? 0))
      }
      K.push(row)
    }
  }
  return K
}

function applyKron(K: readonly (readonly number[])[], v: number): number {
  let out = 0
  for (let o = 0; o < 4; o++) {
    let s = 0
    for (let i = 0; i < 4; i++) s ^= (K[o]?.[i] ?? 0) & ((v >> i) & 1)
    if (s !== 0) out |= 1 << o
  }
  return out
}

/** N=2 (4x4x4 cells) F_2 mismatch for 4-bit-mask terms. */
export function mmSmall(terms: readonly Small4[]): number {
  const bits4 = (m: number): number[] => {
    const o: number[] = []
    for (let i = 0; i < 4; i++) {
      if (((m >> i) & 1) !== 0) o.push(i)
    }
    return o
  }
  const acc = new Uint8Array(64)
  for (const t of terms) {
    for (const a of bits4(t.u)) {
      for (const b of bits4(t.v)) {
        for (const c of bits4(t.w)) acc[a * 16 + b * 4 + c] = (acc[a * 16 + b * 4 + c] ?? 0) ^ 1
      }
    }
  }
  let bad = 0
  for (let a = 0; a < 4; a++) {
    for (let b = 0; b < 4; b++) {
      for (let c = 0; c < 4; c++) {
        const i = Math.floor(a / 2)
        const j = a % 2
        const j2 = Math.floor(b / 2)
        const k = b % 2
        const i2 = Math.floor(c / 2)
        const k2 = c % 2
        const want = j === j2 && k === k2 && i === i2 ? 1 : 0
        if ((acc[a * 16 + b * 4 + c] ?? 0) !== want) bad++
      }
    }
  }
  return bad
}

/** All distinct exact 7-term <2,2,2> schemes in the sandwich orbit (4-bit masks). */
export function innerOrbit(): Small4[][] {
  const base: Small4[] = SU.map((_, i) => ({
    u: mask4of(SU[i] ?? 0),
    v: mask4of(SV[i] ?? 0),
    w: mask4of(SW[i] ?? 0),
  }))
  const seen = new Map<string, Small4[]>()
  for (const P of GL2) {
    for (const Q of GL2) {
      for (const R of GL2) {
        const KU = kron2(tr2(inv2(P)), Q)
        const KV = kron2(tr2(inv2(Q)), R)
        const KW = kron2(P, tr2(inv2(R)))
        const terms = base.map((t) => ({
          u: applyKron(KU, t.u),
          v: applyKron(KV, t.v),
          w: applyKron(KW, t.w),
        }))
        if (mmSmall(terms) !== 0) throw new Error("R118 orbit member inexact")
        const k = terms
          .map((t) => `${t.u},${t.v},${t.w}`)
          .sort()
          .join(";")
        if (!seen.has(k)) seen.set(k, terms)
      }
    }
  }
  return [...seen.values()]
}

/** Transpose symmetry of <2,2,2>: swap u/v + transpose 2x2 masks. */
export function transposeSmall(terms: readonly Small4[]): Small4[] {
  const tr4 = (m: number): number => {
    let out = 0
    for (let i = 0; i < 2; i++) {
      for (let j = 0; j < 2; j++) {
        if (((m >> (i * 2 + j)) & 1) !== 0) out |= 1 << (j * 2 + i)
      }
    }
    return out
  }
  return terms.map((t) => ({ u: tr4(t.v), v: tr4(t.u), w: tr4(t.w) }))
}

/** Lift 4-bit outer/inner masks to a 16-bit factor mask. */
export function lift16(outer: number, inner: number): number {
  let m = 0
  for (let p = 0; p < 2; p++) {
    for (let pp = 0; pp < 2; pp++) {
      if (((outer >> (p * 2 + pp)) & 1) === 0) continue
      for (let q = 0; q < 2; q++) {
        for (let qp = 0; qp < 2; qp++) {
          if (((inner >> (q * 2 + qp)) & 1) === 0) continue
          m |= 1 << ((2 * p + q) * 4 + (2 * pp + qp))
        }
      }
    }
  }
  return m
}

/**
 * Product seed: outer 7-term scheme x per-fiber inner 7-term schemes.
 * Exact whenever every inner scheme (and the outer) is exact.
 */
export function productSeed(
  outer: readonly Small4[],
  inners: readonly (readonly Small4[])[],
): FT[] {
  const out: FT[] = []
  for (let o = 0; o < 7; o++) {
    const O = outer[o] ?? { u: 0, v: 0, w: 0 }
    const inner = inners[o] ?? []
    for (let q = 0; q < 7; q++) {
      const I = inner[q] ?? { u: 0, v: 0, w: 0 }
      out.push([lift16(O.u, I.u), lift16(O.v, I.v), lift16(O.w, I.w)])
    }
  }
  return out
}

/* ---------------- F_2 instrument (agrees with checker.verifyMod2) ---------------- */

function bits(x: number): number[] {
  const out = new Array<number>(16).fill(0)
  for (let i = 0; i < 16; i++) out[i] = (x >> i) & 1
  return out
}

export function maskOf(v: readonly number[]): number {
  let m = 0
  for (let i = 0; i < 16 && i < v.length; i++) {
    if (((v[i] ?? 0) & 1) !== 0) m |= 1 << i
  }
  return m
}

function pop16(x: number): number {
  let v = x & 0xffff
  let n = 0
  while (v !== 0) {
    n += v & 1
    v >>>= 1
  }
  return n
}

function supp(x: number): number[] {
  const out: number[] = []
  for (let i = 0; i < 16; i++) {
    if (((x >> i) & 1) !== 0) out.push(i)
  }
  return out
}

const TARGET = new Uint8Array(4096)
{
  const loc = (bi: number, bj: number, q: number, qp: number): number =>
    (2 * bi + q) * 4 + (2 * bj + qp)
  for (let bi = 0; bi < 2; bi++) {
    for (let bj = 0; bj < 2; bj++) {
      for (let bk = 0; bk < 2; bk++) {
        for (let q = 0; q < 2; q++) {
          for (let qq = 0; qq < 2; qq++) {
            for (let qqq = 0; qqq < 2; qqq++) {
              TARGET[loc(bi, bj, q, qq) * 256 + loc(bj, bk, qq, qqq) * 16 + loc(bi, bk, q, qqq)] = 1
            }
          }
        }
      }
    }
  }
}

export function mismatches(terms: readonly FT[]): number {
  const got = new Uint8Array(4096)
  for (const t of terms) {
    const A = supp(t[0])
    const B = supp(t[1])
    const C = supp(t[2])
    for (const a of A) {
      for (const b of B) {
        for (const c of C) got[a * 256 + b * 16 + c] = (got[a * 256 + b * 16 + c] ?? 0) ^ 1
      }
    }
  }
  let mm = 0
  for (let i = 0; i < 4096; i++) {
    if (got[i] !== (TARGET[i] ?? 0)) mm++
  }
  return mm
}

function sumCells(terms: readonly FT[], idx: readonly number[]): Uint8Array {
  const out = new Uint8Array(4096)
  for (const k of idx) {
    const t = terms[k]
    if (t === undefined) continue
    const A = supp(t[0])
    const B = supp(t[1])
    const C = supp(t[2])
    for (const a of A) {
      for (const b of B) {
        for (const c of C) out[a * 256 + b * 16 + c] = (out[a * 256 + b * 16 + c] ?? 0) ^ 1
      }
    }
  }
  return out
}

function f2Witness(s: Uint8Array): FT | null {
  let a0 = -1
  let b0 = -1
  let c0 = -1
  for (let a = 0; a < 16 && a0 < 0; a++) {
    for (let b = 0; b < 16 && a0 < 0; b++) {
      for (let c = 0; c < 16; c++) {
        if (s[a * 256 + b * 16 + c] !== 0) {
          a0 = a
          b0 = b
          c0 = c
          break
        }
      }
    }
  }
  if (a0 < 0) return null
  let P = 0
  let Q = 0
  let R = 0
  for (let a = 0; a < 16; a++) {
    if ((s[a * 256 + b0 * 16 + c0] ?? 0) !== 0) P |= 1 << a
  }
  for (let b = 0; b < 16; b++) {
    if ((s[a0 * 256 + b * 16 + c0] ?? 0) !== 0) Q |= 1 << b
  }
  for (let c = 0; c < 16; c++) {
    if ((s[a0 * 256 + b0 * 16 + c] ?? 0) !== 0) R |= 1 << c
  }
  for (let a = 0; a < 16; a++) {
    if (((P >> a) & 1) === 0) continue
    for (let b = 0; b < 16; b++) {
      if (((Q >> b) & 1) === 0) continue
      for (let c = 0; c < 16; c++) {
        const want = (R >> c) & 1
        if (((s[a * 256 + b * 16 + c] ?? 0) !== 0 ? 1 : 0) !== want) return null
      }
    }
  }
  let ones = 0
  for (let i = 0; i < 4096; i++) ones += s[i] ?? 0
  if (ones !== pop16(P) * pop16(Q) * pop16(R)) return null
  return [P, Q, R]
}

/** Stable canonical hash over F_2 masks (same fnv as the R99-R112 drain lanes). */
export function fnv(terms: readonly FT[]): string {
  let h = 0x811c9dc5
  for (const t of terms) {
    for (const x of t) {
      h ^= (x & 0xffff) + 0x9e37
      h = Math.imul(h, 0x01000193) >>> 0
    }
  }
  return (h >>> 0).toString(16).padStart(8, "0")
}

export function termsOf(start: StartState): FT[] {
  return start.masks.map((m) => [m[0] ?? 0, m[1] ?? 0, m[2] ?? 0] as FT)
}

export function schemeOf(terms: readonly FT[]): Scheme {
  return {
    n: N,
    triples: terms.map((t) => ({ u: bits(t[0]), v: bits(t[1]), w: bits(t[2]) })),
  }
}

export function vecOf(terms: readonly FT[]): number[][][] {
  return terms.map((t) => [bits(t[0]), bits(t[1]), bits(t[2])])
}

export function isExact(terms: readonly FT[]): boolean {
  return mismatches(terms) === 0
}

export function mulberry(seed: number): () => number {
  let a = seed >>> 0
  return () => {
    a = (a + 0x6d2b79f5) >>> 0
    let t = Math.imul(a ^ (a >>> 15), 1 | a)
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}

/* ---------------- starts: fresh R118-size anchor subset ---------------- */

/**
 * Hashes already covered by the sweepA/v2 drain lanes — never drained here
 * as orbit inputs. 4126ca7f: rank-53 spark anchor (R99-sweepA input).
 * 6098903c: R99 snap-ILS rank-47 near-miss support (ILS object, not a
 * drain input).
 */
export const SKIP_TOUCHED: readonly string[] = ["4126ca7f", "6098903c"]

export function isSkippedTouched(hash: string): boolean {
  return SKIP_TOUCHED.includes(hash)
}

/**
 * Fresh R118-size anchor subset: WIDER enumeration than R117 over the same
 * own-construction product family, on a disjoint enumeration offset, keeping
 * ONLY supports whose snapped hash is absent from the R105-best set, the
 * R106 combined set, the R107 fresh set, the R109 fresh set, the R112 fresh
 * set, the R113 fresh set, the R116 fresh set, AND the R117 fresh set (and
 * from the touched drain-lane hashes). Every kept support is exact-49 at
 * build (length 49, mm 0), verified here, never asserted. Capped at
 * MAX_STARTS so a full run stays bounded; the cap keeps the FIRST fresh
 * supports in deterministic enumeration order.
 */
function buildFreshR118(
  r105Snaps: ReadonlySet<string>,
  r106Snaps: ReadonlySet<string>,
  r107Snaps: ReadonlySet<string>,
  r109Snaps: ReadonlySet<string>,
  r112Snaps: ReadonlySet<string>,
  r113Snaps: ReadonlySet<string>,
  r116Snaps: ReadonlySet<string>,
  r117Snaps: ReadonlySet<string>,
): StartState[] {
  const orbit = innerOrbit()
  const orbitT = orbit.map(transposeSmall)
  const base = orbit[0] ?? []
  const baseT = orbitT[0] ?? [...base]
  const rep = (m: readonly Small4[]): Small4[][] => Array.from({ length: 7 }, () => [...m])
  const cands: { tag: string; outer: readonly Small4[]; inners: readonly (readonly Small4[])[] }[] = []
  const n = orbit.length
  const nn = n === 0 ? 1 : n
  const nT = orbitT.length === 0 ? 1 : orbitT.length
  // Outer-transpose lane with a rotated inner fiber (R116 used stride
  // (13,7), R117 used stride (17,11): disjoint by construction, filtered
  // anyway).
  for (let i = 0; i < orbitT.length; i++) {
    const m = orbitT[i]
    const f = orbit[(i * 19 + 5) % nn]
    if (m !== undefined && f !== undefined)
      cands.push({ tag: `r118-outT-${i}`, outer: m, inners: rep(f) })
  }
  // Cross outer/inner pairings on strides disjoint from R116's (11,3)/(19,5)
  // and R117's (13,7)/(23,11).
  for (let i = 0; i < n; i++) {
    const o = orbit[(i * 17 + 3) % nn]
    const m = orbit[(i * 29 + 7) % nn]
    if (o !== undefined && m !== undefined) cands.push({ tag: `r118-cross-${i}`, outer: o, inners: rep(m) })
  }
  // Eighth mixed-fiber rotation (disjoint offset from R106's (5,3,1),
  // R107's (7,5,3), R109's (13,7,5), R112's (11,3,7), R113's (7,5,11),
  // R116's (5,7,13) and R117's (7,11,17)).
  for (let s = 0; s < 12; s++) {
    const inners: Small4[][] = []
    for (let o = 0; o < 7; o++) {
      const m = orbit[(o * 11 + s * 13 + 19) % nn]
      inners.push(m === undefined ? [...base] : [...m])
    }
    cands.push({ tag: `r118-mixF8-${s}`, outer: baseT, inners })
  }
  // Seventh mixed transpose-fiber rotation (disjoint from R107's (11,7,5),
  // R109's (7,11,2), R112's (5,13,3), R113's (13,7,9), R116's (7,11,5) and
  // R117's (11,13,7)).
  for (let s = 0; s < 8; s++) {
    const inners: Small4[][] = []
    for (let o = 0; o < 7; o++) {
      const m = orbitT[(o * 13 + s * 17 + 11) % nT]
      inners.push(m === undefined ? [...base] : [...m])
    }
    cands.push({ tag: `r118-mixT7-${s}`, outer: base, inners })
  }
  const out: StartState[] = []
  const seen = new Set<string>()
  for (const s of r105Snaps) seen.add(s)
  for (const s of r106Snaps) seen.add(s)
  for (const s of r107Snaps) seen.add(s)
  for (const s of r109Snaps) seen.add(s)
  for (const s of r112Snaps) seen.add(s)
  for (const s of r113Snaps) seen.add(s)
  for (const s of r116Snaps) seen.add(s)
  for (const s of r117Snaps) seen.add(s)
  let seed = 60001
  for (const c of cands) {
    if (out.length >= MAX_STARTS) break
    const terms = productSeed(c.outer, c.inners)
    if (terms.length !== 49 || mismatches(terms) !== 0) continue
    const snap = fnv(terms)
    if (isSkippedTouched(snap) || seen.has(snap)) continue
    seen.add(snap)
    out.push({
      tag: c.tag,
      originHash: `r118-size:${c.tag}`,
      seed,
      kind: "orbit",
      snapHash: snap,
      masks: terms.map((t) => [t[0], t[1], t[2]] as readonly [number, number, number]),
    })
    seed++
  }
  return out
}

function buildStarts(): StartState[] {
  const r105Snaps = new Set(R105_STARTS.map((s) => s.snapHash))
  const r106Snaps = new Set(R106_STARTS.map((s) => s.snapHash))
  const r107Snaps = new Set(R107_STARTS.map((s) => s.snapHash))
  const r109Snaps = new Set(R109_STARTS.map((s) => s.snapHash))
  const r112Snaps = new Set(R112_STARTS.map((s) => s.snapHash))
  const r113Snaps = new Set(R113_STARTS.map((s) => s.snapHash))
  const r116Snaps = new Set(R116_STARTS.map((s) => s.snapHash))
  const r117Snaps = new Set(R117_STARTS.map((s) => s.snapHash))
  return buildFreshR118(r105Snaps, r106Snaps, r107Snaps, r109Snaps, r112Snaps, r113Snaps, r116Snaps, r117Snaps)
}

export const STARTS: readonly StartState[] = buildStarts()

/** Fresh supports added beyond the R105, R106, R107, R109, R112, R113 and R116 sets. */
export const R118_FRESH_ADDED: number = STARTS.length

export const ORBIT_SIZE: number = (() => {
  try {
    return innerOrbit().length
  } catch {
    return -1
  }
})()

function anchorStart(): StartState {
  const s = STARTS[0]
  if (s === undefined) throw new Error("R118: no fresh start states built")
  return s
}

/** Exported state: the first fresh exact-49. Gate stays RED (49 > 47). */
export const scheme: Scheme = schemeOf(termsOf(anchorStart()))

/* ---------------- moves: greedy exact F_2 drain, flips, splits, meld ---------------- */

/** Greedy exact F_2 drain: annihilate + merge2/merge3. Mutates terms. */
export function drain(terms: FT[], allowTriple: boolean): string[] {
  const chain: string[] = []
  for (let guard = 0; guard < 8; guard++) {
    let hit: { idx: number[]; m: FT } | null = null
    outer1: for (let i = 0; i < terms.length && hit === null; i++) {
      for (let j = i + 1; j < terms.length; j++) {
        const s = sumCells(terms, [i, j])
        let any = false
        for (let k = 0; k < 4096; k++) {
          if ((s[k] ?? 0) !== 0) {
            any = true
            break
          }
        }
        if (!any) {
          hit = { idx: [i, j], m: [0, 0, 0] }
          break outer1
        }
      }
    }
    if (hit === null) {
      outer2: for (let i = 0; i < terms.length && hit === null; i++) {
        for (let j = i + 1; j < terms.length; j++) {
          const m = f2Witness(sumCells(terms, [i, j]))
          if (m !== null) {
            hit = { idx: [i, j], m }
            break outer2
          }
        }
      }
    }
    if (hit === null && allowTriple && terms.length <= 56) {
      outer3: for (let i = 0; i < terms.length && hit === null; i++) {
        for (let j = i + 1; j < terms.length && hit === null; j++) {
          for (let k = j + 1; k < terms.length; k++) {
            const m = f2Witness(sumCells(terms, [i, j, k]))
            if (m !== null) {
              hit = { idx: [i, j, k], m }
              break outer3
            }
          }
        }
      }
    }
    if (hit === null) break
    const before = terms.length
    const rm = new Set(hit.idx)
    const nt = terms.filter((_, k) => !rm.has(k))
    if (hit.m[0] !== 0) nt.push(hit.m)
    terms.length = 0
    terms.push(...nt)
    chain.push(`m${hit.idx.length}:${before}->${terms.length}`)
  }
  if (!isExact(terms)) chain.push("BROKEN")
  return chain
}

/** F_2 shear on a pair sharing exactly one axis. Returns true if moved. */
export function f2Flip(terms: FT[], i: number, j: number, rnd: () => number): boolean {
  const ti = terms[i]
  const tj = terms[j]
  if (ti === undefined || tj === undefined || i === j) return false
  const sh: number[] = []
  for (let a = 0; a < 3; a++) {
    if (ti[a] === tj[a]) sh.push(a)
  }
  if (sh.length === 0) return false
  const ax = sh[Math.floor(rnd() * sh.length)] ?? 0
  if (ax === 0) {
    const nv = ti[1] ^ tj[1]
    const nw = tj[2] ^ ti[2]
    if (nv === 0 || nw === 0) return false
    terms[i] = [ti[0], nv, ti[2]]
    terms[j] = [tj[0], tj[1], nw]
  } else if (ax === 1) {
    const nw = ti[2] ^ tj[2]
    const nu = tj[0] ^ ti[0]
    if (nw === 0 || nu === 0) return false
    terms[i] = [ti[0], ti[1], nw]
    terms[j] = [nu, tj[1], tj[2]]
  } else {
    const nu = ti[0] ^ tj[0]
    const nv = ti[1] ^ tj[1]
    if (nu === 0 || nv === 0) return false
    terms[i] = [nu, nv, ti[2]]
    terms[j] = [tj[0], tj[1], tj[2]]
  }
  return true
}

export function f2Split(terms: FT[], i: number, rnd: () => number): boolean {
  const t = terms[i]
  if (t === undefined) return false
  const ax = Math.floor(rnd() * 3)
  const f = t[ax] ?? 0
  const nz = supp(f)
  if (nz.length < 2) return false
  let f1 = 0
  let f2 = 0
  for (const p of nz) {
    if (rnd() < 0.5) f1 |= 1 << p
    else f2 |= 1 << p
  }
  if (f1 === 0 || f2 === 0) return false
  const c1: FT = [t[0], t[1], t[2]]
  const c2: FT = [t[0], t[1], t[2]]
  c1[ax] = f1
  c2[ax] = f2
  terms[i] = c1
  terms.push(c2)
  return true
}

/**
 * Deterministic meld: alternating-halves child of two exact parents,
 * deduplicated, then drained back toward exactness. Returns the child and
 * its drain chain (chain includes BROKEN when the child never re-lands
 * exact — the caller discards such children, never checkpoints them).
 */
export function meld(
  a: readonly FT[],
  b: readonly FT[],
  rnd: () => number,
): { child: FT[]; chain: string[] } {
  const child: FT[] = []
  const seen = new Set<string>()
  const n = Math.max(a.length, b.length)
  for (let k = 0; k < n; k++) {
    const src =
      k % 2 === 0
        ? (a[k] ?? b[k % (b.length === 0 ? 1 : b.length)])
        : (b[k] ?? a[k % (a.length === 0 ? 1 : a.length)])
    if (src === undefined) continue
    const key = `${src[0]},${src[1]},${src[2]}`
    if (seen.has(key)) continue
    seen.add(key)
    child.push([src[0], src[1], src[2]])
  }
  // deterministic micro-perturbation so distinct seeds explore distinct kids
  for (let f = 0; f < 8; f++) {
    if (child.length < 2) break
    const i = Math.floor(rnd() * child.length)
    let j = Math.floor(rnd() * (child.length - 1))
    if (j >= i) j++
    f2Flip(child, i, j, rnd)
  }
  const chain = drain(child, false)
  return { child, chain: ["meld", ...chain] }
}

/**
 * Exact F_2 Gaussian elimination over packed bit rows (recovered machinery,
 * same semantics as the R100 snap-spark gaussSolve). Returns the solution
 * vector or null when the system is inconsistent.
 */
export function gaussSolve(
  nvars: number,
  rows: readonly { coef: readonly number[]; rhs: number }[],
): number[] | null {
  const words = Math.ceil(nvars / 32)
  const m = rows.map((r) => ({ coef: [...r.coef], rhs: r.rhs }))
  const where = new Array<number>(nvars).fill(-1)
  let row = 0
  for (let col = 0; col < nvars && row < m.length; col++) {
    let sel = -1
    for (let i = row; i < m.length; i++) {
      const mr = m[i]
      if (mr !== undefined && (((mr.coef[col >> 5] ?? 0) >> (col & 31)) & 1) !== 0) {
        sel = i
        break
      }
    }
    if (sel < 0) continue
    const tmp = m[sel] as { coef: number[]; rhs: number }
    m[sel] = m[row] as { coef: number[]; rhs: number }
    m[row] = tmp
    where[col] = row
    for (let i = 0; i < m.length; i++) {
      if (i === row) continue
      const ri = m[i]
      const rr = m[row]
      if (ri !== undefined && rr !== undefined && (((ri.coef[col >> 5] ?? 0) >> (col & 31)) & 1) !== 0) {
        for (let k = 0; k < words; k++) ri.coef[k] = ((ri.coef[k] ?? 0) ^ (rr.coef[k] ?? 0)) >>> 0
        ri.rhs ^= rr.rhs
      }
    }
    row++
  }
  for (let i = row; i < m.length; i++) {
    const ri = m[i]
    if (ri === undefined) continue
    let allZero = true
    for (let k = 0; k < words; k++) {
      if ((ri.coef[k] ?? 0) !== 0) allZero = false
    }
    if (allZero && ri.rhs !== 0) return null
  }
  const sol = new Array<number>(nvars).fill(0)
  for (let col = 0; col < nvars; col++) {
    const w = where[col] ?? -1
    if (w >= 0) {
      const mr = m[w]
      sol[col] = mr === undefined ? 0 : mr.rhs
    } else sol[col] = 0
  }
  return sol
}

function targetCell(a: number, b: number, c: number): number {
  return TARGET[a * 256 + b * 16 + c] ?? 0
}

/**
 * Fixed-support exact solve in-window: for a zero-mismatch rank<=47
 * candidate, re-solve each factor axis linearly with the other two axes
 * fixed (4096-cell F_2 system per axis via gaussSolve). All three axes
 * must re-solve consistent. Returns true only then; the witness close path
 * requires this plus verifyMod2 plus goalSatisfiedA.
 */
export function exactSolveFixedSupport(terms: readonly FT[]): boolean {
  const R = terms.length
  if (R === 0 || R > TARGET_RANK) return false
  for (const axis of [0, 1, 2] as const) {
    const words = Math.ceil(R / 32)
    for (let f = 0; f < 16; f++) {
      const rows: { coef: number[]; rhs: number }[] = []
      for (let g1 = 0; g1 < 16; g1++) {
        for (let g2 = 0; g2 < 16; g2++) {
          const coef = new Array<number>(words).fill(0)
          let a = 0
          let b = 0
          let c = 0
          if (axis === 0) {
            a = f
            b = g1
            c = g2
          } else if (axis === 1) {
            a = g1
            b = f
            c = g2
          } else {
            a = g1
            b = g2
            c = f
          }
          for (let t = 0; t < R; t++) {
            const tm = terms[t]
            if (tm === undefined) continue
            const m1 = axis === 0 ? tm[1] : tm[0]
            const m2 = axis === 0 ? tm[2] : axis === 1 ? tm[2] : tm[1]
            const i1 = axis === 0 ? b : a
            const i2 = axis === 2 ? b : c
            if ((((m1 >> i1) & 1) & ((m2 >> i2) & 1)) !== 0) {
              coef[t >> 5] = (((coef[t >> 5] ?? 0) | (1 << (t & 31))) >>> 0)
            }
          }
          rows.push({ coef, rhs: targetCell(a, b, c) })
        }
      }
      if (gaussSolve(R, rows) === null) return false
    }
  }
  return true
}

/**
 * The goalCheckA gate path for one candidate scheme: F_2 ground truth
 * (verifyMod2) fed into the M8 predicate (goalSatisfiedA). Returns the
 * winning entry, or undefined while the gate stays red.
 */
export function gateCheckA(candidate: Scheme, file: string): GoalEntry | undefined {
  const v = verifyMod2(candidate)
  const entry: GoalEntry = { file, n: candidate.n, correct: v.correct, rank: v.rank, mismatches: v.mismatches }
  return goalSatisfiedA([entry])
}

/**
 * In-window close gate for a rank<=47 zero-mismatch candidate: verifyMod2
 * ground truth, the goalCheckA predicate, and the fixed-support
 * gaussSolve must ALL agree. Returns the winning entry or undefined.
 */
export function closeCandidate(candidate: Scheme): GoalEntry | undefined {
  if (candidate.triples.length > TARGET_RANK) return undefined
  const v = verifyMod2(candidate)
  if (!v.correct || v.mismatches !== 0) return undefined
  const masks: FT[] = candidate.triples.map((t) => {
    let u = 0
    let wv = 0
    let ww = 0
    for (let i = 0; i < 16 && i < t.u.length; i++) if ((t.u[i] ?? 0) !== 0) u |= 1 << i
    for (let i = 0; i < 16 && i < t.v.length; i++) if ((t.v[i] ?? 0) !== 0) wv |= 1 << i
    for (let i = 0; i < 16 && i < t.w.length; i++) if ((t.w[i] ?? 0) !== 0) ww |= 1 << i
    return [u, wv, ww] as FT
  })
  if (!exactSolveFixedSupport(masks)) return undefined
  return gateCheckA(candidate, "R118_drain49j.ts")
}

export type DrainOutcome = {
  readonly bestRank: number
  readonly bestHash: string
  readonly witness: boolean
  readonly iters: number
  readonly merges: number
  readonly flips: number
  readonly melds: number
}

/**
 * Bounded deterministic drain/meld from one exact start. Pure (no fs)
 * except via onBest, so tests stay fast. Only exact (mm 0) improvements
 * are reported via onBest; witness is true only for an in-window
 * closeCandidate-verified rank<=47 candidate (verifyMod2 AND goalSatisfiedA
 * AND fixed-support gaussSolve all agree).
 */
export function boundedDrain(
  start: FT[],
  rnd: () => number,
  maxIters: number,
  onBest: (terms: FT[], chain: string[]) => void,
): DrainOutcome {
  let cur = start.map((t) => [...t] as FT)
  let best = cur.map((t) => [...t] as FT)
  let bestRank = cur.length
  let bestHash = fnv(cur)
  let merges = 0
  let flips = 0
  let melds = 0
  const witness = false
  let iters = 0
  onBest(best, ["replay"])
  {
    const work = best.map((t) => [...t] as FT)
    const chain = drain(work, true)
    if (!chain.includes("BROKEN") && work.length < bestRank) {
      merges++
      best = work.map((t) => [...t] as FT)
      bestRank = work.length
      bestHash = fnv(best)
      onBest(best, [...chain, "drain-first"])
      if (bestRank <= TARGET_RANK && closeCandidate(schemeOf(best)) !== undefined) {
        return { bestRank, bestHash, witness: true, iters, merges, flips, melds }
      }
      cur = best.map((t) => [...t] as FT)
    }
  }
  for (let it = 0; it < maxIters; it++) {
    iters = it + 1
    if (it % 8 === 7) {
      // meld week: child of cur x best, drain back
      const { child, chain } = meld(cur, best, rnd)
      melds++
      if (!chain.includes("BROKEN") && child.length < bestRank && isExact(child)) {
        merges++
        best = child.map((t) => [...t] as FT)
        bestRank = child.length
        bestHash = fnv(best)
        onBest(best, chain)
        if (bestRank <= TARGET_RANK && closeCandidate(schemeOf(best)) !== undefined) {
          return { bestRank, bestHash, witness: true, iters, merges, flips, melds }
        }
        cur = best.map((t) => [...t] as FT)
        continue
      }
    }
    const probe = cur.map((t) => [...t] as FT)
    if (it % 4 === 3) {
      for (let k = 0; k < 2; k++) f2Split(probe, Math.floor(rnd() * probe.length), rnd)
    }
    for (let f = 0; f < 24; f++) {
      if (probe.length < 2) break
      const a = Math.floor(rnd() * probe.length)
      let b = Math.floor(rnd() * (probe.length - 1))
      if (b >= a) b++
      if (f2Flip(probe, a, b, rnd)) flips++
    }
    const pchain = drain(probe, false)
    if (pchain.includes("BROKEN")) continue
    if (!isExact(probe)) continue
    if (probe.length < bestRank) {
      merges++
      best = probe.map((t) => [...t] as FT)
      bestRank = probe.length
      bestHash = fnv(best)
      onBest(best, [...pchain, "flip-interleave"])
      if (bestRank <= TARGET_RANK && closeCandidate(schemeOf(best)) !== undefined) {
        return { bestRank, bestHash, witness, iters, merges, flips, melds }
      }
      cur = best.map((t) => [...t] as FT)
    }
  }
  return { bestRank, bestHash, witness, iters, merges, flips, melds }
}

/* ---------------- checkpoints: vec-plus-hash rows, resume-skip, witnesses ---------------- */

function hashesInFile(path: string): Set<string> {
  try {
    const text = readFileSync(path, "utf-8")
    const out = new Set<string>()
    for (const line of text.split("\n")) {
      if (line.trim() === "") continue
      try {
        const r = JSON.parse(line) as { hash?: unknown }
        if (typeof r.hash === "string") out.add(r.hash)
      } catch {
        continue
      }
    }
    return out
  } catch {
    return new Set<string>()
  }
}

/**
 * Resume-skip set: hashes already checkpointed by this round, hashes
 * already checkpointed in R100_drain49.ndjson, hashes already checkpointed
 * in R101_drain49b.ndjson (graceful when absent), plus R106/R107/R108/R109
 * checkpoint hashes, R111 lane hashes, and R112/R113/R116/R117 checkpoint
 * hashes when those files exist next to this file. Every read is graceful,
 * never a throw; skips are logged by the caller, not silent.
 */
export function checkpointedHashes(): Set<string> {
  const out = hashesInFile(NDJSON)
  for (const h of hashesInFile(R100_NDJSON)) out.add(h)
  for (const h of hashesInFile(R101_NDJSON)) out.add(h)
  for (const h of hashesInFile(R106_NDJSON)) out.add(h)
  for (const h of hashesInFile(R107_NDJSON)) out.add(h)
  for (const h of hashesInFile(R108_NDJSON)) out.add(h)
  for (const h of hashesInFile(R109_NDJSON)) out.add(h)
  for (const h of hashesInFile(R111_NDJSON)) out.add(h)
  for (const h of hashesInFile(R112_NDJSON)) out.add(h)
  for (const h of hashesInFile(R113_NDJSON)) out.add(h)
  for (const h of hashesInFile(R116_NDJSON)) out.add(h)
  for (const h of hashesInFile(R117_NDJSON)) out.add(h)
  return out
}

/** Vec-plus-hash checkpoint row: every best state lands with its full bit vecs and stable hash. */
export function bestRow(
  from: string,
  chain: readonly string[],
  terms: readonly FT[],
): Record<string, unknown> {
  const v = verifyMod2(schemeOf(terms))
  return {
    t: Date.now(),
    mode: terms.length <= TARGET_RANK ? "R118-WIN" : "R118-drain-best",
    task: TASK_ID,
    from,
    chain: [...chain],
    rank: terms.length,
    hash: fnv(terms),
    vec: vecOf(terms),
    mod2: v.correct,
    mm: v.mismatches,
  }
}

function log(row: unknown): void {
  appendFileSync(NDJSON, `${JSON.stringify(row)}\n`, "utf-8")
}

// no-excuse-ok: catch
async function main(): Promise<void> {
  try {
    const itersArg = Number.parseInt(process.argv[2] ?? `${ITERS_PER_START}`, 10)
    const seedArg = Number.parseInt(process.argv[3] ?? `${SEED_BASE}`, 10)
    const iters = effectiveIters(Number.isFinite(itersArg) ? itersArg : ITERS_PER_START)
    const sbase = Number.isFinite(seedArg) ? seedArg : SEED_BASE
    const done = checkpointedHashes()
    let wins = 0
    let processed = 0
    let skipped = 0
    let bestFirst: FT[] | null = null
    let bestSecond: FT[] | null = null
    const half = Math.ceil(STARTS.length / 2)
    for (const s of STARTS) {
      if (isSkippedTouched(s.originHash) || isSkippedTouched(s.snapHash)) {
        skipped++
        log({ t: Date.now(), mode: "R118-skip-touched", task: TASK_ID, hash: s.originHash, snap: s.snapHash })
        console.log(`R118 skip (touched drain-lane hash): ${s.originHash} snap=${s.snapHash}`)
        continue
      }
      if (done.has(s.snapHash)) {
        skipped++
        log({ t: Date.now(), mode: "R118-skip-checkpointed", task: TASK_ID, hash: s.originHash, snap: s.snapHash })
        console.log(`R118 skip (already checkpointed): ${s.originHash} snap=${s.snapHash}`)
        continue
      }
      processed++
      const terms = termsOf(s)
      const mm0 = mismatches(terms)
      const hash0 = fnv(terms)
      const laneSeed = sbase + s.seed
      const rnd = mulberry(laneSeed)
      log({
        t: Date.now(),
        mode: "R118-drain-start",
        task: TASK_ID,
        from: s.originHash,
        tag: s.tag,
        snap: s.snapHash,
        kind: s.kind,
        seed: laneSeed,
        rank: terms.length,
        mm: mm0,
        hash: hash0,
        vec: vecOf(terms),
      })
      console.log(`R118 drain: tag=${s.tag} from=${s.originHash} snap=${hash0} rank=${terms.length} mm=${mm0} kind=${s.kind}`)
      let lastBest: FT[] = terms.map((t) => [...t] as FT)
      const onBest = (t: FT[], chain: string[]): void => {
        lastBest = t.map((x) => [...x] as FT)
        const row = bestRow(s.originHash, chain, t)
        log(row)
        console.log(`R118 BEST from=${s.originHash} chain=${chain.join(" ")} rank=${t.length} hash=${fnv(t)} mod2=${row["mod2"]}`)
      }
      const outcome = boundedDrain(terms, rnd, iters, onBest)
      const idx = STARTS.indexOf(s)
      if (idx < half && (bestFirst === null || lastBest.length < bestFirst.length)) {
        bestFirst = lastBest.map((t) => [...t] as FT)
      }
      if (idx >= half && (bestSecond === null || lastBest.length < bestSecond.length)) {
        bestSecond = lastBest.map((t) => [...t] as FT)
      }
      if (outcome.witness) {
        wins++
        log({ t: Date.now(), mode: "R118-WIN", task: TASK_ID, from: s.originHash, bestRank: outcome.bestRank, bestHash: outcome.bestHash, vec: vecOf(lastBest) })
        console.log(`R118 WIN: rank ${outcome.bestRank} hash=${outcome.bestHash}`)
      } else {
        log({
          t: Date.now(),
          mode: "R118-drain-end-RED",
          task: TASK_ID,
          from: s.originHash,
          tag: s.tag,
          bestRank: outcome.bestRank,
          bestHash: outcome.bestHash,
          iters: outcome.iters,
          merges: outcome.merges,
          flips: outcome.flips,
          melds: outcome.melds,
          verdict: VERDICT_BOUNDED,
          note: `bounded drain, no rank<=${TARGET_RANK} witness; measured best ${outcome.bestRank}, did not measure exhaustion`,
        })
        console.log(
          `R118 RED: from=${s.originHash} best=${outcome.bestRank} hash=${outcome.bestHash} iters=${outcome.iters} merges=${outcome.merges} flips=${outcome.flips} melds=${outcome.melds}`,
        )
      }
    }
    if (bestFirst !== null && bestSecond !== null && wins === 0) {
      const xrnd = mulberry(sbase + 9019)
      const { child, chain } = meld(bestFirst, bestSecond, xrnd)
      if (!chain.includes("BROKEN") && isExact(child)) {
        const row = bestRow("cross:r118-halves", chain, child)
        log(row)
        console.log(`R118 CROSS-MELD rank=${child.length} hash=${fnv(child)} mod2=${row["mod2"]}`)
        if (child.length <= TARGET_RANK && closeCandidate(schemeOf(child)) !== undefined) {
          wins++
          log({ t: Date.now(), mode: "R118-WIN", task: TASK_ID, from: "cross:r118-halves", bestRank: child.length, bestHash: fnv(child), vec: vecOf(child) })
          console.log(`R118 WIN (cross-meld): rank ${child.length} hash=${fnv(child)}`)
        }
      } else {
        log({ t: Date.now(), mode: "R118-cross-meld-RED", task: TASK_ID, note: "cross-family child never re-landed exact; discarded, not checkpointed as best" })
        console.log("R118 CROSS-MELD RED: child inexact, discarded")
      }
    }
    console.log(`R118 done: processed=${processed} skipped=${skipped} wins=${wins} verdict=${verdictFor(wins > 0)}`)
    if (wins === 0 && processed === 0 && skipped > 0) {
      console.log("R118 note: every start was already processed or checkpointed; nothing new measured this run")
    }
  } catch (e) {
    console.error("unhandled:", e)
    process.exit(1)
  }
}

if (import.meta.main) {
  await main()
}
